<?php $title='Categories';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($name));$pdo->prepare("INSERT INTO categories(name,slug,description,image,active) VALUES(?,?,?,?,1)")->execute([$name,$slug,trim($_POST['description']),trim($_POST['image'])]);} $cats=$pdo->query("SELECT * FROM categories ORDER BY id")->fetchAll();?><div class="row g-4"><div class="col-lg-5"><h2>Add Category</h2><form method="post" class="card p-4 border-0 shadow-sm"><input required name="name" class="form-control mb-2" placeholder="Category Name"><textarea name="description" class="form-control mb-2" placeholder="Description"></textarea><input name="image" class="form-control mb-2" placeholder="Image URL"><button class="btn btn-primary">Add Category</button></form></div><div class="col-lg-7"><h2>Categories</h2><div class="list-group"><?php foreach($cats as $c):?><div class="list-group-item d-flex justify-content-between"><span><?=e($c['name'])?></span><small><?=e($c['slug'])?></small></div><?php endforeach;?></div></div></div><?php require 'includes/footer.php';?>